            "text": "معظم الذرات ترتبط مع ذرات أخرى بروابط كيميائية لتكوين جزيئات ومواد جديدة، فما هي الرابطة الكيميائية؟ وكيف ترتبط الذرات ببعضها للوصول إلى حالة الاستقرار؟\n\nأهداف الفصل الأول:\n1. التعرف على البناء الذري ومستويات الطاقة وسعة الأغلفة الإلكترونية (K, L, M).\n2. فهم دور إلكترونات التكافؤ في تحديد السلوك الكيميائي للذرة.\n3. التمييز بين الذرة المتعادلة والأيون (الموجب والسالب) ومفهوم التأين.\n4. استيعاب قواعد حساب أعداد التأكسد والتكافؤ للعناصر والمجاميع الذرية.\n5. دراسة نشوء الرابطة الأيونية والرابطة التساهمية ورسم الترتيب الإلكتروني لها."
