            "heading": "قواعد حساب أعداد التأكسد والمجاميع الذرية الشائعة (صفحة 12)",
            "text": "القواعد الأساسية لحساب أعداد التأكسد:\n1. عدد تأكسد أي عنصر حر غير متحد (مثل Na, Fe, H₂, O₂, Cl₂) يساوي صفراً (0).\n2. عدد تأكسد الأيون أحادي الذرة يساوي شحنة ذلك الأيون (مثال: Na⁺ هو +1، و Al³⁺ هو +3، و Cl⁻ هو -1).\n3. عدد تأكسد الهيدروجين في مركباته يساوي دائماً (+1) [عدا الهيدريدات الفلزية مثل NaH حيث يكون -1].\n4. عدد تأكسد الأكسجين في مركباته يساوي دائماً (-2) [عدا البيروكسيدات مثل H₂O₂ حيث يكون -1].\n5. المجموع الجبري لأعداد التأكسد لجميع الذرات في مركب متعادل يساوي صفراً (0).\n6. المجموع الجبري لأعداد التأكسد لجميع الذرات في أيون متعدد الذرات (مجموعة ذرية) يساوي شحنة ذلك الأيون.\n\nأهم المجاميع الذرية وشحناتها المعتمدة:\n- الهيدروكسيد (OH⁻): -1\n- النترات (NO₃⁻): -1\n- النتريت (NO₂⁻): -1\n- الأمونيوم (NH₄⁺): +1\n- الكبريتات (SO₄²⁻): -2\n- الكربونات (CO₃²⁻): -2\n- الفوسفات (PO₄³⁻): -3"
