            "heading": "الرابطة التساهمية (Covalent Bond) وأمثلة الجزيئات (صفحة 18)",
            "diagram_id": "diag_covalent_bonding_molecules",
            "text": "1. تعريف الرابطة التساهمية:\nهي قوة ربط كيميائية ناشئة بين ذرتين (غالباً لافلزات) نتيجة مشاركة كل ذرة بإلكترون واحد أو أكثر لتكوين زوج إلكتروني مشترك أو أكثر.\n\n2. الزوج الإلكتروني المشترك:\nهو زوج من الإلكترونات (أحدهما من الذرة الأولى والآخر من الذرة الثانية) يدور في الحيز بين النواتين ويربطهما بقوة تساهمية. يرمز له بخط وصل (-) أو نقطتين (:) كما في تمثيل لويس.\n\n3. نماذج الجزيئات التساهمية الشائعة:\n- جزيء الهيدروجين (H₂): تساهم كل ذرة هيدروجين بإلكترونها الوحيد لتكوين رابطة تساهمية أحادية (H-H) فيمتلك كل منهما غلافاً ممتلئاً بـ 2e⁻ كالهيليوم.\n- جزيء الفلور (F₂): تساهم كل ذرة فلور بإلكترون واحد لتكوين رابطة أحادية (F-F) ويكتمل الغلاف بـ 8e⁻ كالنيون.\n- جزيء الماء (H₂O): تساهم ذرة الأكسجين بإلكترونين لتكوين رابطتين تساهميتين أحاديتين مع ذرتي هيدروجين (H-O-H).\n- جزيء الميثان (CH₄): تساهم ذرة الكربون المركزية بـ 4 إلكترونات تكافؤ مع 4 ذرات هيدروجين لتكوين أربع روابط تساهمية أحادية."
