                    "a": "• البالونان المدلوكان بالصوف يكتسبان شحنة سالبة متشابهة فيتنافران عند تقريبهما من بعضهما، بينما ينجذب البالون المشحون إلى الحائط المتعادل بسبب استقطاب الشحنات في الحائط (تجاذب الشحنات المختلفة).\n• وجه الشبه: كما تنجذب الشحنات الكهربائية المتضادة بين البالون والحائط، تنجذب الأيونات ذات الشحنات الكهربائية المختلفة (الموجبة والسالبة) لتكوين الروابط الكيميائية."
