    "description": "الصفحات 23 - 34: النشاط الاستهلالي (التجاذب بين الجزيئات والتوتر السطحي)، خواص المركبات الأيونية والتساهمية والمقارنة الشاملة بينهما، قوى الترابط بين الجزيئات (قوى فان در فال، الرابطة الهيدروجينية، شذوذ خواص الماء)، مع مراجعات الدروس وحلول مراجعة الفصل الثاني الشاملة.",
