            "heading": "شذوذ خواص الماء بفعل الرابطة الهيدروجينية وحماية الحياة المائية (صفحة 31)",
            "diagram_id": "diag_intermolecular_forces_hbond",
            "text": "الظواهر الفريدة الناتجة عن الرابطة الهيدروجينية في الماء:\n1. ارتفاع غير متوقع لدرجتي الغليان والانصهار:\nيغلي الماء عند 100°C وينصهر عند 0°C وهي درجات مرتفعة جداً مقارنة بالمركبات المشابهة في الحجم والكتلة ككبريتيد الهيدروجين H₂S (غاز في درجة حرارة الغرفة).\n\n2. شذوذ الكثافة (طفو الجليد):\n- السوائل تزداد كثافتها كلما انخفضت درجة حرارتها حتى تتجمد فتهبط للقعر.\n- أما الماء فتقل كثافته عندما تنخفض حرارته تحت 4°C؛ حيث تترتب جزيئاته بفعل الروابط الهيدروجينية في بناء بلوري سداسي مجوف تتسع فيه المسافات البينية ويزداد حجمه.\n- النتيجة: الجليد أقل كثافة من الماء السائل فيطفو على السطح مشكلاً طبقة عازلة تحفظ حرارة المياه العميقة عند 4°C وتحمي الأسماك والكائنات المائية من التجمد والموت في الشتاء القطبي القارس.\n\n3. ظاهرة التوتر السطحي (Surface Tension):\nقوة جذب جزيئات الماء لبعضها عند السطح تشكل غشاءً مرناً مشدوداً يفسر طفو الإبرة المعدنية ومشي بعض الحشرات على سطح الماء."
