            "heading": "ربط الكيمياء بالمباحث الأخرى: الألكتروليتات والبروتينات والمايكروويف (صفحة 32)",
            "text": "1. ربط الكيمياء بالأحياء (الألكتروليتات):\nهي المركبات الأيونية التي تذوب في الماء وتوصل التيار الكهربائي، ولها دور حيوي مهم في عمل الخلايا والأعصاب، وتُفقد أثناء النشاط البدني المكثف أو المرض لذا يلزم تعويضها.\n\n2. علاقة الكيمياء بجسم الإنسان (البروتينات والعناصر الضرورية):\n• البروتينات: جزيئات حيوية معقدة تتكون من الأحماض الأمينية وترتبط بآلاف الروابط التساهمية.\n• العناصر الأساسية: تشكل عناصر (الأكسجين والكاربون والهيدروجين والنيتروجين) 96% من كتلة جسم الإنسان، والكالسيوم والفسفور 3%، والصوديوم والبوتاسيوم والكلوريد والمغنيسيوم 0.7%.\n\n3. علاقة الروابط الكيميائية بالطعام (فرن المايكروويف):\nيعمل المايكروويف بإرسال إشعاعات بتردد قرابة 3 GHz تُحدث اهتزازات سريعة في روابط جزيئات الماء داخل الطعام فتولد حرارة تسبب طهيه."
