    "description": "الصفحات 35 - 54: الصيغ الكيميائية وقواعد كتابتها، حساب عدد الذرات والكتل الصيغية، المعادلة الكيميائية وموازنتها وقانون حفظ الكتلة، أنواع التفاعلات الكيميائية الخمسة، التفاعلات الباعثة والماصة للطاقة وتطبيق أكياس الهواء (Airbags)، مع مراجعات الدروس وحلول مراجعة الفصل الثالث.",
