            "diagram_id": "diag_chemical_formula_anatomy",
            "text": "1. أمثلة محلولة لحساب عدد الذرات (صفحة 40):\n• مثال 5: احسب عدد ذرات كل عنصر في 3Na₂CO₃:\n  - الصوديوم (Na) = 3 × 2 = 6 ذرات.\n  - الكاربون (C) = 3 × 1 = 3 ذرات.\n  - الأوكسجين (O) = 3 × 3 = 9 ذرات.\n• مثال 6: ماذا تعني الأرقام في Al₂(SO₄)₃؟\n  - عدد ذرات الألمنيوم = 2، عدد ذرات الأوكسجين في المجموعة = 4، وعدد مجاميع الكبريتات = 3.\n\n2. جدول (3-2) البادئات المستخدمة في الأسماء الكيميائية للمركبات التساهمية:\n1: أحادي (mono) • 2: ثنائي (di) • 3: ثلاثي (tri) • 4: رباعي (tetra) • 5: خماسي (penta) • 6: سداسي (hexa) • 7: سباعي (hepta) • 8: ثماني (octa) • 9: تساعي (nona) • 10: عُشاري (deca).\n• أمثلة التسمية: CO₂ (ثنائي أوكسيد الكاربون)، N₂O (أحادي أوكسيد ثنائي النتروجين)."
