            "text": "1. قانون حفظ الكتلة (Law of Conservation of Mass):\n\"المادة لا تفنى ولا تستحدث أثناء التفاعل الكيميائي، وإنما يعاد ترتيب ذراتها لتكوين مواد جديدة\".\nلذا يجب أن يكون مجموع كتل المواد المتفاعلة مساوياً تماماً لمجموع كتل المواد الناتجة.\n\n2. شرط المعادلة الموزونة:\nيجب أن يكون عدد ذرات كل عنصر في طرف المواد المتفاعلة (يسار) مساوياً لعدد ذرات ذلك العنصر نفسه في طرف المواد الناتجة (يمين).\n\n3. قاعدة الموازنة الذهبية:\nتتم الموازنة حصراً بوضع أو تعديل الأرقام الكبيرة (المعاملات) على يسار الصيغ الكيميائية، ويُحظر تماماً تغيير الأرقام السفلية للصيغ لأن ذلك يغير التركيب الكيميائي للمادة."
