                    "a": "لأن دقائق المادة المنتشرة في الغروي تكون دقيقة الحجم (1–1000 نانومتر) وتتوزع بانتظام فلا تترسب عند تركها ولا تُفصل بالترشيح (مثل الحليب والضباب)، لكنها تشتت الضوء بظاهرة تندال."
