            "text": "لماذا يعد الماء مذيباً عاماً (Universal Solvent)؟\n1. قطبية جزيء الماء العالية: لذرة الأكسجين كهروسلبية عالية تجعلها سالبة جزئياً (δ⁻) وذرتي الهيدروجين موجبتين جزئياً (δ⁺).\n2. القدرة على إحاطة الأيونات وفصلها: تجذب أقطاب الماء الأيونات الموجبة والسالبة للمركبات الأيونية وتضعف التجاذب بينها فتذيبها بسهولة.\n3. تكوين روابط هيدروجينية: يستطيع الماء تكوين روابط هيدروجينية مع المركبات التساهمية القطبية كالسكر والكحول فيذيبها."
