            "diagram_id": "diag_solubility_factors",
            "text": "كيف تتشكل الهوابط والصواعد (Stalactites & Stalagmites)؟\n1. إذابة الصخور الجيرية:\nيحتوي ماء المطر على غاز ثاني أكسيد الكربون الذائب مشكلاً حامض الكاربونيك المخفف H₂CO₃، فيذيب صخور كربونات الكالسيوم الجيرية CaCO₃ غير الذائبة ويحولها إلى بيكربونات الكالسيوم الذائبة Ca(HCO₃)₂.\n\n2. تشكل الهوابط والصواعد:\n- عندما يقطر الماء المحمل بالبيكربونات من سقف الكهف، يتبخر جزء من الماء ويتصاعد غاز CO₂.\n- تترسب كربونات الكالسيوم الصلبة مجدداً نقطة وراء نقطة مكونة أعمدة صخرية كلسية تتدلى من السقف تسمى (الهوابط Stalactites).\n- والنقاط التي تسقط على أرضية الكهف تبني أعمدة صاعدة للأعلى تسمى (الصواعد Stalagmites) عبر آلاف السنين في مشهد جيولوجي كيميائي بديع."
