            "diagram_id": "diag_acids_bases_arrhenius",
            "text": "1. تصنيف القواعد بحسب عدد مجاميع الهيدروكسيل القابلة للتأين:\n- قاعدة أحادية الهيدروكسيل: تولد أيون هيدروكسيد واحداً OH⁻ مثل: هيدروكسيد الصوديوم NaOH، وهيدروكسيد البوتاسيوم KOH.\n- قاعدة ثنائية الهيدروكسيل: تولد أيوني هيدروكسيد OH⁻ مثل: هيدروكسيد الكالسيوم Ca(OH)₂، وهيدروكسيد المغنيسيوم Mg(OH)₂.\n- قاعدة متعددة الهيدروكسيل: مثل هيدروكسيد الألومنيوم Al(OH)₃.\n\n2. تصنيف القواعد بحسب القوة والتركيز:\n- قاعدة قوية: تتأين كلياً في الماء مثل NaOH, KOH.\n- قاعدة ضعيفة: تتأين جزئياً مثل محلول الأمونيا (هيدروكسيد الأمونيوم NH₄OH).\n- قاعدة مركزة وقاعدة مخففة بحسب كمية المذاب مقارنة بكمية الماء.",
