            "diagram_id": "diag_ph_scale_indicators",
            "text": "1. جدول ألوان الدلائل الشائعة (صفحة 84):\n• ورق زهرة الشمس: أزرق/أحمر ➔ أحمر بالحامض / أزرق بالقاعدة.\n• دليل الفينولفثالين: عديم اللون ➔ عديم اللون بالحامض / أحمر وردي بالقاعدة.\n• دليل الميثيل البرتقالي: برتقالي ➔ أحمر بالحامض / أصفر بالقاعدة.\n\n2. التوازن بين أيونات H⁺ و OH⁻ في المحاليل المائية:\n• إذا كانت أيونات الهيدروجين H⁺ أكثر من أيونات الهيدروكسيل OH⁻ يكون المحلول حامضياً.\n• إذا كانت أيونات الهيدروكسيل OH⁻ أكثر من أيونات الهيدروجين H⁺ يكون المحلول قاعدياً.\n• إذا تساوت أيونات H⁺ و OH⁻ يكون المحلول متعادلاً."
