            "text": "قاعدة التسمية النظامية للأملاح:\nيسمى الملح بذكر اسم الأيون السالب للحامض أولاً يليه اسم الأيون الموجب للقاعدة:\n\n1. أملاح حامض الهيدروكلوريك HCl ➔ تسمى (كلوريد):\n- NaCl: كلوريد الصوديوم (ملح الطعام).\n- KCl: كلوريد البوتاسيوم.\n- NH₄Cl: كلوريد الأمونيوم.\n\n2. أملاح حامض الكبريتيك H₂SO₄ ➔ تسمى (كبريتات):\n- Na₂SO₄: كبريتات الصوديوم.\n- CuSO₄: كبريتات النحاس (ملح أزرق).\n- CaSO₄: كبريتات الكالسيوم (الجبس والبياض).\n\n3. أملاح حامض النتريك HNO₃ ➔ تسمى (نترات):\n- KNO₃: نترات البوتاسيوم.\n- AgNO₃: نترات الفضة.\n\n4. أملاح حامض الكاربونيك H₂CO₃ ➔ تسمى (كربونات):\n- CaCO₃: كربونات الكالسيوم (الحجر الجيري والرخام والطباشير).\n- Na₂CO₃: كربونات الصوديوم (صودا الغسيل)."
