            "diagram_id": "diag_laboratory_glassware",
            "text": "المرجع المصور للأدوات المختبرية الرسمية (صفحة 95 من كتاب الوزارة):\n1. أدوات السحب والقياس الدقيق:\n- ماصة إلكترونية (Electronic Pipette).\n- ماصة يدوية عادية ومطاطة سحب.\n- سحاحة زجاجية (Burette) مع صنبور تفريغ.\n- أسطوانة مدرجة (Graduated Cylinder).\n- ميزان رقمي حساس.\n\n2. الأوعية الزجاجية وأواني الخلط:\n- كأس زجاجي (Beaker).\n- دورق مخروطي (Erlenmeyer Flask).\n- قنينة حجمية (Volumetric Flask).\n- أنابيب اختبار (Test Tubes) مع حامل أنابيب وماسك خشبي.\n\n3. أدوات التسخين والمسك والطحن:\n- جهاز السخان والتحريك المغناطيسي (Hotplate Magnetic Stirrer).\n- هاون ومطرقة خزفية (Mortar & Pestle).\n- جفنة خزفية (Crucible).\n- حامل وماسك حديدي (Iron Stand & Clamp).\n- قمع زجاجي (Glass Funnel) وقنينة غسل.\n\n4. خطوات طي ورقة الترشيح الأربع:\n- الخطوة 1: طي ورقة الترشيح الدائرية إلى نصفين متطابقين.\n- الخطوة 2: طي النصفين إلى ربعين متطابقين.\n- الخطوة 3: فتح المخروط بحيث تصبح 3 طبقات بجهة وطبقة واحدة بالجهة المقابلة.\n- الخطوة 4: وضع المخروط داخل القمع الزجاجي وتبليله بقليل من الماء المقطر ليلتصق بجدار القمع بإحكام.",
