    "summary": "إلكترونات الغلاف الخارجي تسمى إلكترونات التكافؤ وهي المسؤولة عن السلوك الكيميائي والترابط.",
    "details": "• العناصر النبيلة (He: 2e⁻, Ne: 8e⁻, Ar: 8e⁻) أغلفتها الخارجية مشبعة تماماً بالإلكترونات، ولذا تمتاز بدرجة عالية من الاستقرار والخمول الكيميائي.\n• تميل الذرات غير المشبعة لفقدان أو اكتساب أو المساهمة بإلكترونات التكافؤ للوصول إلى الترتيب الثماني المشابه للغاز النبيل."
