    "summary": "التكافؤ هو عدد الإلكترونات المفقودة أو المكتسبة أو المساهم بها بدون إشارة، بينما عدد التأكسد يحمل إشارة جبرية (+ أو -).",
    "details": "• التكافؤ عدد صحيح موجب بدون إشارة (أحادي، ثنائي، ثلاثي).\n• عدد التأكسد يشير إلى عدد ونوع الشحنات الكهربائية ويكتب بإشارة جبرية (مثل +1, +2, -1, -2).\n• بعض العناصر لها أكثر من حالة تأكسد مثل الحديد: حديدوز (+2) وحديديك (+3)."
