    "details": "1. عدد تأكسد أي عنصر حر غير متحد = 0 (مثل Na, Fe, H₂, O₂).\n2. عدد تأكسد الهيدروجين في مركباته = +1.\n3. عدد تأكسد الأكسجين في مركباته = -2.\n4. المجموع الجبري لأعداد التأكسد في مركب متعادل = 0.\n5. المجموع الجبري لأعداد التأكسد في مجموعة ذرية = شحنة الأيون."
