        "id": "chem_mid_q5",
        "number": "س5",
        "title": "طاقة التفاعل والدلائل الحسية (20 درجة)",
        "marks": "20 درجة",
        "content": "<p><strong>أ)</strong> ما الفرق بين التفاعل الباعث للحرارة (Exothermic) والتفاعل الماص للحرارة (Endothermic)؟ مع ذكر مثال ومعادلة توضيحية لكل منهما. (10 درجات)</p><p><strong>ب)</strong> اذكر أربعة من الدلائل والمؤشرات التي تؤكد حدوث تفاعل كيميائي مع الأمثلة. (10 درجات)</p>",
        "solution": "<strong>الحل النموذجي وتوزيع الدرجات (20 درجة):</strong><br><strong>فرع (أ) - التفاعلات الحرارية (10 درجات):</strong><br>• <strong>التفاعل الباعث للحرارة:</strong> تفاعل يحرر طاقة حرارية إلى المحيط لأن طاقة المواد الناتجة أقل من طاقة المواد المتفاعلة، وتكتب الطاقة في جهة النواتج، مثل احتراق الغاز الطبيعي: C + O₂ ➔ CO₂ + طاقة (5 درجات).<br>• <strong>التفاعل الماص للحرارة:</strong> تفاعل يمتص طاقة حرارية من المحيط لإتمام التفاعل وتكتب الطاقة في جهة المتفاعلات، مثل تفكك أكسيد الزئبق: 2HgO + طاقة ➔ 2Hg + O₂ (5 درجات).<br><br><strong>فرع (ب) - دلائل حدوث التفاعل (10 درجات - 2.5 درجة لكل نقطة):</strong><br>1. <strong>تغير اللون:</strong> مثل تغير لون صوف الحديد عند صدئه للون البني المحمر.<br>2. <strong>تحرر غاز (تصاعد فقاعات):</strong> مثل تصاعد غاز H₂ عند وضع الخارصين في حامض الهيدروكلوريك.<br>3. <strong>تكون راسب:</strong> مثل تكون راسب أبيض من AgCl عند إضافة نترات الفضة إلى محلول ملح الطعام.<br>4. <strong>انبعاث حرارة أو ضوء:</strong> مثل اشتعال شريط المغنيسيوم بوهج أبيض ساطع."
