        "marks": "20 درجة",
        "content": "<p>عرّف أربعة فقط مما يأتي: (لكل تعريف 5 درجات)</p><ol><li>الرابطة التساهمية</li><li>المحلول المشبع</li><li>قاعدة أرهينيوس</li><li>الرقم الهيدروجيني (pH)</li><li>تفاعل التعادل</li></ol>",
        "solution": "<strong>الحل النموذجي وتوزيع الدرجات (20 درجة - 5 درجات لكل تعريف):</strong><br>1. <strong>الرابطة التساهمية:</strong> قوة ربط تنشأ بين ذرتين لافلزيتين نتيجة مشاركة أو مساهمة كل ذرة بإلكترون تكافؤ واحد أو أكثر لتكوين زوج إلكتروني مشترك للوصول للترتيب الإلكتروني المستقر.<br>2. <strong>المحلول المشبع:</strong> محلول يحتوي على أقصى كمية ممكنة من المذاب التي يمكن أن تذوب في كمية محددة من المذيب عند درجة حرارة وضغط معينين، ولا يستطيع استيعاب أي زيادة إضافية من المذاب.<br>3. <strong>قاعدة أرهينيوس:</strong> مادة تتأين في المحلول المائي لتعطي أيون الهيدروكسيد السالب (OH⁻)، ولها ملمس صابوني وطعم مر وتزرق ورقة زهرة الشمس.<br>4. <strong>الرقم الهيدروجيني (pH):</strong> مقياس عددي لوغاريتمي يتراوح من 0 إلى 14 يحدد درجة حامضية أو قاعدية المحاليل المائية اعتماداً على تركيز أيونات الهيدروجين H⁺؛ فالأقل من 7 حامضي و 7 متعادل والأكبر من 7 قاعدي.<br>5. <strong>تفاعل التعادل:</strong> تفاعل كيميائي بين حامض وقاعدة ينتج عنه ملح وماء، وتتعادل فيه خواص الحامض مع خواص القاعدة (مثل: HCl + NaOH ➔ NaCl + H₂O)."
